1	type Item = { type: string; cursed?: boolean; enchantment?: number };
2	
3	const basePremiumsByType: Record<string, number> = { sword: 100, amulet: 60, staff: 80, potion: 40, rune: 25, moonstone: 25 };
4	
5	const BLOCK_SIZE = 3;
6	const BLOCK_PREMIUM = 60;
7	
8	const sumOverItems = (items: Item[], perItem: (item: Item) => number): number =>
9	  items.reduce((sum, item) => sum + perItem(item), 0);
10	
11	const basePremiumForItem = (item: Item): number => basePremiumsByType[item.type];
12	
13	const sumOfItemBasePremiums = (items: Item[]): number =>
14	  sumOverItems(items, basePremiumForItem);
15	
16	const groupByType = (items: Item[]): Item[][] => {
17	  const groups = new Map<string, Item[]>();
18	  for (const item of items) {
19	    const group = groups.get(item.type) ?? [];
20	    group.push(item);
21	    groups.set(item.type, group);
22	  }
23	  return [...groups.values()];
24	};
25	
26	const basePremiumForGroup = (group: Item[]): number =>
27	  group.length === BLOCK_SIZE ? BLOCK_PREMIUM : sumOfItemBasePremiums(group);
28	
29	export const basePremium = (items: Item[]): number =>
30	  groupByType(items).reduce((sum, group) => sum + basePremiumForGroup(group), 0);
31	
32	const PROCESSING_FEE = 5;
33	
34	type QuoteStep = { op: "quote"; items: Item[] };
35	type Scenario = { customer: { yearsWithMHPCO: number }; steps: QuoteStep[] };
36	
37	const CURSE_SURCHARGE_RATE = 0.5;
38	const HIGH_ENCHANTMENT_RATE = 0.3;
39	const HIGH_ENCHANTMENT_THRESHOLD = 5;
40	const FIRST_INSURANCE_RATE = 0.1;
41	
42	const surchargeOf = (item: Item, rate: number): number => basePremiumForItem(item) * rate;
43	
44	const curseSurchargeForItem = (item: Item): number =>
45	  item.cursed ? surchargeOf(item, CURSE_SURCHARGE_RATE) : 0;
46	
47	const curseSurcharge = (items: Item[]): number =>
48	  sumOverItems(items, curseSurchargeForItem);
49	
50	const highEnchantmentSurchargeForItem = (item: Item): number =>
51	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD
52	    ? surchargeOf(item, HIGH_ENCHANTMENT_RATE)
53	    : 0;
54	
55	const highEnchantmentSurcharge = (items: Item[]): number =>
56	  sumOverItems(items, highEnchantmentSurchargeForItem);
57	
58	const firstInsuranceSurcharge = (policyBase: number): number => policyBase * FIRST_INSURANCE_RATE;
59	
60	const quotePremium = (step: QuoteStep): number => {
61	  const policyBase = basePremium(step.items);
62	  return (
63	    policyBase +
64	    curseSurcharge(step.items) +
65	    highEnchantmentSurcharge(step.items) +
66	    firstInsuranceSurcharge(policyBase) +
67	    PROCESSING_FEE
68	  );
69	};
70	
71	export const runScenario = (scenario: Scenario): { results: { premium: number }[] } => ({
72	  results: scenario.steps.map((step) => ({ premium: quotePremium(step) })),
73	});
