const quotePremium = (step: QuoteStep): number => {
  const items = step.items;
  const policyBase = basePremium(items);
  const surcharges =
    curseSurcharge(items) +
    highEnchantmentSurcharge(items) +
    firstInsuranceSurcharge(policyBase);
  return policyBase + surcharges + PROCESSING_FEE;
};
